    /// <summary>
    /// MPJ_19962_MDRPOTransactionalMissingFields kavya 25/3/2022
    /// </summary>
    /// <param name="sender">Get from form data source</param>
    /// <param name="e">args</param>
    [FormDataSourceEventHandler(formDataSourceStr(PurchTable, PurchLine), FormDataSourceEventType::Writing), SuppressBPWarningAttribute("BPParameterNotUsed", "@MET:BPParameterNotUsedMessage")]
        public static void PurchLine_OnWritting(FormDataSource sender, FormDataSourceEventArgs e)
    {
        FormRun             formRun         = sender.formRun();
        PurchLine           purchLine       = formRun.dataSource(formDataSourceStr(PurchTable,PurchLine)).cursor();
        METPurchTable       METPurchTable   = formRun.dataSource(formDataSourceStr(PurchTable,METPurchTable)).cursor();

        if(METPurchTable.POPromotionIHG && !purchLine.RecId)
        {
            purchLine.METPOLinePromotionIHG = METPurchTable.POPromotionIHG;
        }

        if(!purchLine.RecId && !purchLine::exist(purchLine.purchid))
        {
            ReqItemTable                ReqItemTable;
            PurchTable                  PurchTable   = formRun.dataSource(formDataSourceStr(PurchTable,PurchTable)).cursor();
            InventDim                   InventDimCov;
            METReqItemTable             metReqItemTable;

            select firstonly Planner from metReqItemTable 
                where metReqItemTable.Planner
                exists join reqItemTable
                where reqItemTable.ItemId         == purchLine.ItemId
                &&  reqItemTable.RecId == metReqItemTable.RefRecId
                exists join InventDimCov
                where InventDimCov.inventDimId == reqItemTable.CovInventDimId
                &&  (InventDimCov.InventSiteId == PurchTable.InventSiteId && InventDimCov.InventLocationId == PurchTable.InventLocationId);

            if(metReqItemTable.Planner)
            {
                METPurchTable.POPlannerCode = metReqItemTable.Planner;
            }
            else
            {
                select firstonly Planner from metReqItemTable
                    where metReqItemTable.Planner
                    exists join reqItemTable
                    where reqItemTable.ItemId         == purchLine.ItemId
                    &&  reqItemTable.RecId == metReqItemTable.RefRecId
                    exists join InventDimCov
                    where InventDimCov.inventDimId == reqItemTable.CovInventDimId
                    &&  (InventDimCov.InventSiteId == PurchTable.InventSiteId && InventDimCov.InventLocationId == METConstants::emptyString);

                if(metReqItemTable.Planner)
                {
                    METPurchTable.POPlannerCode = metReqItemTable.Planner;
                }
                else
                {
                    select firstonly Planner from metReqItemTable
                        where metReqItemTable.Planner
                        exists join reqItemTable
                        where reqItemTable.ItemId         == purchLine.ItemId
                        &&  reqItemTable.RecId == metReqItemTable.RefRecId
                        exists join InventDimCov
                        where InventDimCov.inventDimId == reqItemTable.CovInventDimId
                        && (InventDimCov.InventSiteId == METConstants::emptyString) ;

                    if(metReqItemTable.Planner)
                    {
                        METPurchTable.POPlannerCode = metReqItemTable.Planner;
                    }
                }
            }

            if(METPurchTable && METPurchTable.validateWrite())
            {
                METPurchTable.Write();
            }
        }

    }

    /// <summary>
    /// MPJ_19962_MDRPOTransactionalMissingFields kavya 25/3/2022
    /// </summary>
    /// <param name="sender">Get from form data source</param>
    /// <param name="e">args</param>
    [FormDataSourceEventHandler(formDataSourceStr(PurchTable, PurchLine), FormDataSourceEventType::ValidatingWrite), SuppressBPWarningAttribute("BPParameterNotUsed", "@MET:BPParameterNotUsedMessage")]
    public static void PurchLine_OnValidatingWrite(FormDataSource sender, FormDataSourceEventArgs e)
    {
        var             args        = e as FormDataSourceCancelEventArgs;
        FormRun         formRun     = sender.formRun();
        PurchLine       purchLine   = formRun.dataSource(formDataSourceStr(PurchTable,PurchLine)).cursor();

        METPurchTable   METPurchTable = formRun.dataSource(formDataSourceStr(PurchTable,METPurchTable)).cursor();

        if(args != null && METPurchTable.POPromotionIHG && !purchLine.METPOLinePromotionIHG)
        {
            Valid ret = checkFailed("@MET:METPOPromotionValidation");
            args.cancel(ret);
        }
    }

    /// <summary>
    /// Added by kavya on 11/5/2022 for MPJ_19962_MDRPOTransactionalMissingFields - part 2
    /// TO update the change reason code for all the PO Line
    /// </summary>
    /// <param name="sender">Form control</param>
    /// <param name="e">args</param>
    [FormControlEventHandler(formControlStr(PurchTable, METUpdateAllPOChangeReasonCode), FormControlEventType::Clicking), SuppressBPWarningAttribute("BPParameterNotUsed", "@MET:BPParameterNotUsedMessage")]
    public static void METUpdateAllPOChangeReasonCode_OnClicking(FormControl sender, FormControlEventArgs e)
    {
        FormButtonControl   callerButton    = sender as FormButtonControl;  //Retrieves the button that we're reacting to
        FormRun             form            = callerButton.formRun(); //Gets the running formx 
        FormDataSource      PurchTable_ds   = form.dataSource(formDataSourceStr(PurchTable, PurchTable)) as FormDataSource;
        PurchTable          PurchTable      = PurchTable_ds.cursor();

        Dialog              dialog;
        DialogField         reasonCodeDF;

        dialog          = new Dialog("@MET:METUpdateAllLinesReasonCode");
        reasonCodeDF    = dialog.addField(extendedTypeStr(METChangeReasonCode));
        reasonCodeDF.registerOverrideMethod(methodStr(FormStringControl, lookup), methodStr(METPurchTableForm_Extension, METChangeReasonCodeLookup), form);

        dialog.run();

        if (dialog.closedOk())
        {
            PurchLine purchline;

            update_recordset purchline
                setting METPOLineChangeReasonCode = reasonCodeDF.value()
            where purchline.purchid == PurchTable.PurchId;   
        }

    }

